body.script:
(function () {
    const workspace = document.querySelector(".rw-workspace");
    const doc = document.getElementById("rw-document");
    const dropLayer = document.getElementById("rw-drop-layer");
    const saveUrl = workspace ? workspace.dataset.saveUrl : "";
    const saveButton = document.getElementById("rw-save-fields");
    const addButton = document.getElementById("rw-add-signature");
    const status = document.getElementById("rw-status");
    const propLabel = document.getElementById("rw-prop-label");
    const propType = document.getElementById("rw-prop-type");
    const propPage = document.getElementById("rw-prop-page");
    const propX = document.getElementById("rw-prop-x");
    const propY = document.getElementById("rw-prop-y");
    const propWidth = document.getElementById("rw-prop-width");
    const propHeight = document.getElementById("rw-prop-height");
    const propRequired = document.getElementById("rw-prop-required");
    const deleteButton = document.getElementById("rw-delete-field");
    const labels = {
        signature: "Signature",
        initial: "Initials",
        date: "Date",
        text: "Text",
    };
    let active = null;
    let fieldDrag = null;
    let toolDrag = null;
    let suppressToolClick = false;

    if (!doc) {
        return;
    }

    function setStatus(message) {
        if (status) {
            status.textContent = message || "";
        }
    }

    function clamp(value, min, max) {
        const numeric = Number.isFinite(value) ? value : min;
        return Math.max(min, Math.min(max, numeric));
    }

    function percent(value, fallback) {
        const parsed = parseFloat(String(value || "").replace("%", ""));
        return Number.isFinite(parsed) ? parsed : fallback;
    }

    function fieldSize(type) {
        if (type === "date") {
            return {width: 18, height: 4.8};
        }
        if (type === "text") {
            return {width: 30, height: 6};
        }
        if (type === "initial") {
            return {width: 18, height: 7};
        }
        return {width: 28, height: 8};
    }

    function normalizeType(type) {
        return labels[type] ? type : "signature";
    }

    function metricsFromField(field) {
        return {
            pos_x: percent(field.style.left, 8),
            pos_y: percent(field.style.top, 70),
            width: percent(field.style.width, 28),
            height: percent(field.style.height, 8),
        };
    }

    function applyMetrics(field, metrics) {
        const minWidth = 6;
        const minHeight = 3;
        const width = clamp(metrics.width, minWidth, 100);
        const height = clamp(metrics.height, minHeight, 100);
        const left = clamp(metrics.pos_x, 0, 100 - width);
        const top = clamp(metrics.pos_y, 0, 100 - height);
        field.style.left = left.toFixed(3) + "%";
        field.style.top = top.toFixed(3) + "%";
        field.style.width = width.toFixed(3) + "%";
        field.style.height = height.toFixed(3) + "%";
    }

    function pointFromClient(clientX, clientY) {
        const rect = doc.getBoundingClientRect();
        return {
            left: ((clientX - rect.left) / rect.width) * 100,
            top: ((clientY - rect.top) / rect.height) * 100,
        };
    }

    function isInsideDocument(clientX, clientY) {
        const rect = doc.getBoundingClientRect();
        return clientX >= rect.left && clientX <= rect.right && clientY >= rect.top && clientY <= rect.bottom;
    }

    function visibleDefaultPoint() {
        const rect = doc.getBoundingClientRect();
        const top = Math.max(rect.top, 72);
        const bottom = Math.min(rect.bottom, window.innerHeight - 56);
        const safeHeight = Math.max(120, bottom - top);
        return pointFromClient(rect.left + rect.width * 0.22, top + safeHeight * 0.68);
    }

    function setFieldLabel(field, label) {
        const safeLabel = label || labels[normalizeType(field.dataset.fieldType)] || "Signature";
        field.dataset.label = safeLabel;
        const span = field.querySelector("span");
        if (span) {
            span.textContent = safeLabel;
        }
    }

    function createFieldElement(type) {
        const safeType = normalizeType(type);
        const field = document.createElement("div");
        field.className = "rw-field";
        field.dataset.id = "";
        field.dataset.fieldType = safeType;
        field.dataset.required = "1";
        field.dataset.page = "1";

        const label = document.createElement("span");
        label.textContent = labels[safeType];
        const removeButton = document.createElement("button");
        removeButton.type = "button";
        removeButton.className = "rw-field-delete";
        removeButton.title = "Delete field";
        removeButton.textContent = "x";
        const resize = document.createElement("i");
        resize.className = "rw-resize";
        field.appendChild(label);
        field.appendChild(removeButton);
        field.appendChild(resize);
        field.dataset.label = labels[safeType];
        return field;
    }

    function addField(type, point) {
        const safeType = normalizeType(type);
        const size = fieldSize(safeType);
        const dropPoint = point || visibleDefaultPoint();
        const field = createFieldElement(safeType);
        applyMetrics(field, {
            pos_x: dropPoint.left - size.width / 2,
            pos_y: dropPoint.top - size.height / 2,
            width: size.width,
            height: size.height,
        });
        doc.appendChild(field);
        bindField(field);
        selectField(field);
        setStatus("");
        return field;
    }

    function selectField(field) {
        if (active) {
            active.classList.remove("active");
        }
        active = field || null;
        if (!active) {
            propLabel.value = "";
            propType.value = "signature";
            propPage.value = "";
            propX.value = "";
            propY.value = "";
            propWidth.value = "";
            propHeight.value = "";
            propRequired.checked = false;
            return;
        }
        active.classList.add("active");
        propLabel.value = active.dataset.label || labels[normalizeType(active.dataset.fieldType)];
        propType.value = normalizeType(active.dataset.fieldType);
        propPage.value = active.dataset.page || "1";
        propRequired.checked = active.dataset.required !== "0";
        syncPropsFromActive();
    }

    function syncPropsFromActive() {
        if (!active) {
            return;
        }
        const metrics = metricsFromField(active);
        propX.value = metrics.pos_x.toFixed(1);
        propY.value = metrics.pos_y.toFixed(1);
        propWidth.value = metrics.width.toFixed(1);
        propHeight.value = metrics.height.toFixed(1);
    }

    function removeField(field) {
        if (!field) {
            return;
        }
        if (active === field) {
            active = null;
        }
        field.remove();
        selectField(null);
        setStatus("Field removed. Save to apply changes.");
    }

    function bindField(field) {
        if (field.dataset.bound === "1") {
            return;
        }
        field.dataset.bound = "1";
        const removeButton = field.querySelector(".rw-field-delete");
        if (removeButton) {
            removeButton.addEventListener("pointerdown", function (event) {
                event.stopPropagation();
            });
            removeButton.addEventListener("click", function (event) {
                event.preventDefault();
                event.stopPropagation();
                removeField(field);
            });
        }
        field.addEventListener("pointerdown", function (event) {
            if (event.button && event.button !== 0) {
                return;
            }
            const metrics = metricsFromField(field);
            selectField(field);
            field.setPointerCapture(event.pointerId);
            fieldDrag = {
                field: field,
                pointerId: event.pointerId,
                mode: event.target.classList.contains("rw-resize") ? "resize" : "move",
                startX: event.clientX,
                startY: event.clientY,
                startMetrics: metrics,
                docRect: doc.getBoundingClientRect(),
            };
            event.preventDefault();
            event.stopPropagation();
        });
    }

    function moveSelectedField(event) {
        if (!fieldDrag || fieldDrag.pointerId !== event.pointerId) {
            return;
        }
        const dx = ((event.clientX - fieldDrag.startX) / fieldDrag.docRect.width) * 100;
        const dy = ((event.clientY - fieldDrag.startY) / fieldDrag.docRect.height) * 100;
        const next = Object.assign({}, fieldDrag.startMetrics);
        if (fieldDrag.mode === "resize") {
            next.width = fieldDrag.startMetrics.width + dx;
            next.height = fieldDrag.startMetrics.height + dy;
        } else {
            next.pos_x = fieldDrag.startMetrics.pos_x + dx;
            next.pos_y = fieldDrag.startMetrics.pos_y + dy;
        }
        applyMetrics(fieldDrag.field, next);
        if (fieldDrag.field === active) {
            syncPropsFromActive();
        }
        event.preventDefault();
    }

    function stopSelectedField(event) {
        if (fieldDrag && fieldDrag.pointerId === event.pointerId) {
            syncPropsFromActive();
            fieldDrag = null;
        }
    }

    function makeToolGhost(label, x, y) {
        const ghost = document.createElement("div");
        ghost.className = "rw-tool-ghost";
        ghost.textContent = label;
        ghost.style.left = (x + 12) + "px";
        ghost.style.top = (y + 12) + "px";
        document.body.appendChild(ghost);
        return ghost;
    }

    function clearToolDrag() {
        document.querySelectorAll(".rw-tool.dragging").forEach(function (button) {
            button.classList.remove("dragging");
        });
        doc.classList.remove("rw-document-drop-target");
        if (toolDrag && toolDrag.ghost) {
            toolDrag.ghost.remove();
        }
        toolDrag = null;
    }

    function startToolDrag(button, event) {
        if (event.button && event.button !== 0) {
            return;
        }
        const type = normalizeType(button.dataset.type);
        toolDrag = {
            pointerId: event.pointerId,
            type: type,
            startX: event.clientX,
            startY: event.clientY,
            moved: false,
            ghost: makeToolGhost(labels[type], event.clientX, event.clientY),
        };
        button.classList.add("dragging");
        button.setPointerCapture(event.pointerId);
        event.preventDefault();
    }

    function moveTool(event) {
        if (!toolDrag || toolDrag.pointerId !== event.pointerId) {
            return;
        }
        const dx = event.clientX - toolDrag.startX;
        const dy = event.clientY - toolDrag.startY;
        if (Math.abs(dx) + Math.abs(dy) > 4) {
            toolDrag.moved = true;
        }
        toolDrag.ghost.style.left = (event.clientX + 12) + "px";
        toolDrag.ghost.style.top = (event.clientY + 12) + "px";
        doc.classList.toggle("rw-document-drop-target", isInsideDocument(event.clientX, event.clientY));
        event.preventDefault();
    }

    function stopTool(event) {
        if (!toolDrag || toolDrag.pointerId !== event.pointerId) {
            return;
        }
        if (toolDrag.moved && isInsideDocument(event.clientX, event.clientY)) {
            addField(toolDrag.type, pointFromClient(event.clientX, event.clientY));
            suppressToolClick = true;
        }
        clearToolDrag();
    }

    function bindNativeDrop(target) {
        target.addEventListener("dragover", function (event) {
            event.preventDefault();
            event.stopPropagation();
            doc.classList.add("rw-document-drop-target");
        });
        target.addEventListener("drop", function (event) {
            event.preventDefault();
            event.stopPropagation();
            const type = normalizeType(
                event.dataTransfer.getData("application/x-radwan-sign-field") ||
                event.dataTransfer.getData("text/plain")
            );
            addField(type, pointFromClient(event.clientX, event.clientY));
            clearToolDrag();
        });
    }

    function updateActiveMetricsFromInputs() {
        if (!active) {
            return;
        }
        applyMetrics(active, {
            pos_x: parseFloat(propX.value || "0"),
            pos_y: parseFloat(propY.value || "0"),
            width: parseFloat(propWidth.value || "0"),
            height: parseFloat(propHeight.value || "0"),
        });
        syncPropsFromActive();
    }

    document.querySelectorAll(".rw-field").forEach(function (field) {
        applyMetrics(field, metricsFromField(field));
        bindField(field);
    });

    document.querySelectorAll(".rw-tool").forEach(function (button) {
        button.addEventListener("pointerdown", function (event) {
            startToolDrag(button, event);
        });
        button.addEventListener("click", function () {
            if (suppressToolClick) {
                suppressToolClick = false;
                return;
            }
            addField(button.dataset.type);
        });
        button.addEventListener("dragstart", function (event) {
            const type = normalizeType(button.dataset.type);
            event.dataTransfer.effectAllowed = "copy";
            event.dataTransfer.setData("application/x-radwan-sign-field", type);
            event.dataTransfer.setData("text/plain", type);
            button.classList.add("dragging");
            doc.classList.add("rw-document-drop-target");
        });
    });

    document.addEventListener("pointermove", function (event) {
        moveSelectedField(event);
        moveTool(event);
    }, true);
    document.addEventListener("pointerup", function (event) {
        stopSelectedField(event);
        stopTool(event);
    }, true);
    document.addEventListener("pointercancel", function (event) {
        stopSelectedField(event);
        if (toolDrag && toolDrag.pointerId === event.pointerId) {
            clearToolDrag();
        }
    }, true);

    bindNativeDrop(doc);
    if (dropLayer) {
        bindNativeDrop(dropLayer);
    }

    if (addButton) {
        addButton.addEventListener("click", function () {
            addField("signature");
        });
    }

    propLabel.addEventListener("input", function () {
        if (!active) {
            return;
        }
        setFieldLabel(active, propLabel.value);
    });
    propType.addEventListener("change", function () {
        if (!active) {
            return;
        }
        const oldLabel = active.dataset.label || "";
        const oldType = normalizeType(active.dataset.fieldType);
        const newType = normalizeType(propType.value);
        active.dataset.fieldType = newType;
        if (!oldLabel || oldLabel === labels[oldType]) {
            setFieldLabel(active, labels[newType]);
            propLabel.value = labels[newType];
        }
    });
    propPage.addEventListener("input", function () {
        if (active) {
            active.dataset.page = propPage.value || "1";
        }
    });
    [propX, propY, propWidth, propHeight].forEach(function (input) {
        input.addEventListener("input", updateActiveMetricsFromInputs);
        input.addEventListener("change", updateActiveMetricsFromInputs);
    });
    propRequired.addEventListener("change", function () {
        if (active) {
            active.dataset.required = propRequired.checked ? "1" : "0";
        }
    });
    deleteButton.addEventListener("click", function () {
        if (!active) {
            return;
        }
        removeField(active);
    });

    saveButton.addEventListener("click", function () {
        if (!saveUrl) {
            setStatus("Save URL is missing.");
            return;
        }
        saveButton.disabled = true;
        setStatus("Saving...");
        const items = Array.from(doc.querySelectorAll(".rw-field")).map(function (field) {
            const metrics = metricsFromField(field);
            return {
                id: field.dataset.id ? parseInt(field.dataset.id, 10) : false,
                field_type: normalizeType(field.dataset.fieldType),
                label: field.dataset.label || labels[normalizeType(field.dataset.fieldType)],
                required: field.dataset.required !== "0",
                page: parseInt(field.dataset.page || "1", 10),
                pos_x: metrics.pos_x,
                pos_y: metrics.pos_y,
                width: metrics.width,
                height: metrics.height,
            };
        });
        fetch(saveUrl, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "X-Requested-With": "XMLHttpRequest",
            },
            body: JSON.stringify({jsonrpc: "2.0", method: "call", params: {items: items}}),
        }).then(function (response) {
            return response.json();
        }).then(function (payload) {
            if (payload.error) {
                throw new Error(payload.error.data && payload.error.data.message ? payload.error.data.message : "Save failed.");
            }
            setStatus("Saved.");
            window.location.reload();
        }).catch(function (error) {
            setStatus(error.message || "Save failed.");
            saveButton.disabled = false;
        });
    });

    const firstField = doc.querySelector(".rw-field");
    if (firstField) {
        selectField(firstField);
    }
})();

(function () {
    const form = document.getElementById("rw-sign-form");
    if (!form) { return; }
    const payloadInput = document.getElementById("item_payload");
    const firstSignatureInput = document.getElementById("signature_data");
    const signerNameInput = document.getElementById("rw-signer-name");
    const canvases = Array.from(document.querySelectorAll("canvas[data-canvas-id]"));
    const contexts = new Map();
    let activeCanvas = null;
    let drawing = false;

    function setupCanvas(canvas) {
        const context = canvas.getContext("2d");
        contexts.set(canvas.dataset.canvasId, {canvas: canvas, context: context, signed: false});
        resizeCanvas(canvas, context);
    }
    function resizeCanvas(canvas, context) {
        const ratio = Math.max(window.devicePixelRatio || 1, 1);
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * ratio;
        canvas.height = rect.height * ratio;
        context.setTransform(ratio, 0, 0, ratio, 0, 0);
        context.lineCap = "round";
        context.lineJoin = "round";
        context.lineWidth = 2.2;
        context.strokeStyle = "#082f49";
    }
    function point(canvas, event) {
        const rect = canvas.getBoundingClientRect();
        const source = event.touches ? event.touches[0] : event;
        return {x: source.clientX - rect.left, y: source.clientY - rect.top};
    }
    function start(event) {
        const canvas = event.target;
        const item = contexts.get(canvas.dataset.canvasId);
        activeCanvas = canvas;
        drawing = true;
        item.signed = true;
        const p = point(canvas, event);
        item.context.beginPath();
        item.context.moveTo(p.x, p.y);
        event.preventDefault();
    }
    function draw(event) {
        if (!drawing || !activeCanvas) { return; }
        const item = contexts.get(activeCanvas.dataset.canvasId);
        const p = point(activeCanvas, event);
        item.context.lineTo(p.x, p.y);
        item.context.stroke();
        event.preventDefault();
    }
    function stop(event) {
        drawing = false;
        activeCanvas = null;
        if (event) { event.preventDefault(); }
    }
    function fillAutoSignature(item, text) {
        const canvas = item.canvas;
        const context = item.context;
        context.clearRect(0, 0, canvas.width, canvas.height);
        const rect = canvas.getBoundingClientRect();
        context.save();
        context.font = "600 " + Math.max(18, rect.height * 0.36) + "px Segoe UI, Arial";
        context.fillStyle = "#172554";
        context.textAlign = "center";
        context.textBaseline = "middle";
        context.fillText(text || "Signature", rect.width / 2, rect.height / 2);
        context.restore();
        item.signed = true;
    }
    function fillUploadedSignature(item, image) {
        const canvas = item.canvas;
        const context = item.context;
        const rect = canvas.getBoundingClientRect();
        context.clearRect(0, 0, canvas.width, canvas.height);
        context.drawImage(image, 8, 8, Math.max(20, rect.width - 16), Math.max(20, rect.height - 16));
        item.signed = true;
    }
    canvases.forEach(function (canvas) {
        setupCanvas(canvas);
        canvas.addEventListener("mousedown", start);
        canvas.addEventListener("mousemove", draw);
        canvas.addEventListener("mouseup", stop);
        canvas.addEventListener("mouseleave", stop);
        canvas.addEventListener("touchstart", start, { passive: false });
        canvas.addEventListener("touchmove", draw, { passive: false });
        canvas.addEventListener("touchend", stop, { passive: false });
    });
    window.addEventListener("resize", function () {
        contexts.forEach(function (item) { resizeCanvas(item.canvas, item.context); });
    });
    document.getElementById("rw-clear-signature").addEventListener("click", function () {
        contexts.forEach(function (item) {
            item.context.clearRect(0, 0, item.canvas.width, item.canvas.height);
            item.signed = false;
        });
        document.querySelectorAll("input[data-input-id]").forEach(function (input) { input.value = ""; });
    });
    document.getElementById("rw-auto-signature").addEventListener("click", function () {
        contexts.forEach(function (item) {
            fillAutoSignature(item, signerNameInput.value);
        });
    });
    document.getElementById("rw-upload-trigger").addEventListener("click", function () {
        document.getElementById("rw-upload-signature").click();
    });
    document.getElementById("rw-upload-signature").addEventListener("change", function (event) {
        let file = false;
        if (event.target.files) {
            file = event.target.files[0];
        }
        if (!file) { return; }
        const reader = new FileReader();
        reader.onload = function () {
            const image = new Image();
            image.onload = function () {
                contexts.forEach(function (item) {
                    fillUploadedSignature(item, image);
                });
            };
            image.src = reader.result;
        };
        reader.readAsDataURL(file);
    });
    form.addEventListener("submit", function (event) {
        const payload = {};
        let firstSignature = "";
        let missing = false;
        document.querySelectorAll(".rw-sign-box").forEach(function (box) {
            const id = box.dataset.itemId;
            if (box.dataset.type === "signature" || box.dataset.type === "initial") {
                const item = contexts.get(id);
                let data = "";
                if (item) {
                    if (item.signed) {
                        data = item.canvas.toDataURL("image/png");
                    }
                }
                if (box.dataset.required === "1") {
                    if (!data) { missing = true; }
                }
                payload[id] = {signature_data: data};
                if (!firstSignature) {
                    if (data) { firstSignature = data; }
                }
            } else {
                const input = box.querySelector("input");
                const value = input ? input.value : "";
                if (box.dataset.required === "1") {
                    if (!value) { missing = true; }
                }
                payload[id] = {value: value};
            }
        });
        if (missing) {
            event.preventDefault();
            alert("Please complete all required fields.");
            return;
        }
        payloadInput.value = JSON.stringify(payload);
        firstSignatureInput.value = firstSignature;
    });
})();
